# Lesson 2, part 2: value along the life of a bond: right after a payment, right before a payment, and between payment dates.
# Questions 3, 4 and 2 of the lesson 2 file, at the file's own addresses, then two checks and two new practice questions.
_h = 1.0609 ** 0.5 - 1
assert round(_fin.NPV(_h, 4, 24, 3.2, 23.2, 2.4, 22.4, 1.6, 21.6, 0.8, 20.8), 4) == 105.3195
assert round(_fin.NPV(_h, 24, 3.2, 23.2, 2.4, 22.4, 1.6, 21.6, 0.8, 20.8) * 1.0609 ** 0.25, 4) == 106.0347
assert round(_fin.NPV(_h, 1.6, 21.6, 0.8, 20.8) * (1 + _h), 4) == 42.3599
assert round(_fin.NPV(1.0201 ** 0.5 - 1, 27, 1.5, 26.5, 1, 26, 0.5, 25.5) * 1.0201 ** (4 / 12), 4) == 104.5695
assert round(_fin.NPV(_h, 5, 5, 5, 5, 30, 3.75, 28.75, 2.5, 27.5, 1.25, 26.25) * 1.0609 ** 0.25, 4) == 115.6206

